-- db3_stationery_shop
--
-- SQL source of db/db3_stationery_shop.db, generated by tools/dump-schema.py.
-- Rebuild the database with:
--     sqlite3 db/db3_stationery_shop.db < schema/db3_stationery_shop.sql
-- Then check it with:
--     python3 tools/check-db.py

BEGIN TRANSACTION;
CREATE TABLE Category (Category_ID INTEGER PRIMARY KEY ON CONFLICT FAIL, Category_Name CHAR (20) NOT NULL ON CONFLICT ROLLBACK);
CREATE TABLE Customer (Customer_ID CHAR (4) PRIMARY KEY ON CONFLICT FAIL, First_Name CHAR (40), Last_Name CHAR (20) NOT NULL ON CONFLICT ROLLBACK, Email CHAR (50) NOT NULL ON CONFLICT ROLLBACK, Phone_Number CHAR (15) NOT NULL ON CONFLICT ROLLBACK, Address CHAR (200) NOT NULL ON CONFLICT ROLLBACK);
CREATE TABLE Order_Item (Order_Item_ID CHAR (10) PRIMARY KEY ON CONFLICT FAIL, Order_ID CHAR (12) REFERENCES Orders (Order_ID) ON DELETE RESTRICT ON UPDATE RESTRICT MATCH "FULL", Product_ID CHAR (8) REFERENCES Product (Product_ID) ON DELETE RESTRICT ON UPDATE RESTRICT MATCH "FULL", Quantity INTEGER DEFAULT 0, Selling_Price REAL);
CREATE TABLE Orders (Order_ID CHAR (8) PRIMARY KEY ON CONFLICT FAIL, Customer_ID CHAR (4) REFERENCES Customer (Customer_ID) ON DELETE RESTRICT ON UPDATE RESTRICT MATCH "FULL", Order_Date DATE NOT NULL ON CONFLICT ROLLBACK, Total_Amount REAL DEFAULT 0, Status CHAR (10));
CREATE TABLE Product (Product_ID CHAR (8) PRIMARY KEY ON CONFLICT FAIL, Product_Name CHAR (50) NOT NULL ON CONFLICT ROLLBACK, Description CHAR (255), Marked_Price Real DEFAULT 0, Category_ID INTEGER REFERENCES Category (Category_ID) ON DELETE RESTRICT ON UPDATE RESTRICT MATCH "FULL", Quantity INTEGER DEFAULT (0));
COMMIT;
